namespace ghidra.features.bsim.gui.filters;



using org.postgresql.core;

using ghidra.features.bsim.query.client;
using ghidra.features.bsim.query.client;
using ghidra.features.bsim.query.description;
using ghidra.features.bsim.query.elastic;
using ghidra.features.bsim.query.protocol;

/**
 * A BsimFilterType for filtering on functions by the starting path of their containing program.
 */
public class PathStartsBSimFilterType : BSimFilterType {
	public static readonly string XML_VALUE = "pathstarts";

	public PathStartsBSimFilterType() : base("Path starts with", XML_VALUE, "path")
    {
	}

	/* @Override */
	public void gatherSQLEffect(SQLEffects effect, FilterAtom atom, IDSQLResolution resolution)
    {
		if (atom.value.length() > 0) {
			effect.setExeTable();
			effect.setPathTable();
			StringBuilder buf = new StringBuilder();
			buf.append("position( '");
			Utils.escapeLiteral(buf, atom.value, true);
			buf.append("' in pathtable.val) = 1");
			effect.addWhere(this, buf.toString());
		}
	}

	/* @Override */
	public void gatherElasticEffect(ElasticEffects effect, FilterAtom atom,
			IDElasticResolution resolution)
    {
		effect.addDocValue("String path = doc['path'].size() == 0 ? null : doc['path'].value; ");
		string argName = effect.assignArgument();
		effect.addScriptElement(this, "(path != null) && path.startsWith(params." + argName + ')');
		effect.addParam(argName, atom.value);
	}

	/* @Override */
	public bool evaluate(ExecutableRecord rec, string value) {
		if (rec.getPath() == null) {
			return false;
		}
		return rec.getPath().startsWith(value);
	}

	/* @Override */
	public string normalizeValue(string value) {
		value = value.trim();
		// If the string is empty, it's invalid, just return false.
		if (value.isBlank()) {
			return null;
		}
		int pos = 0;
		int posend = value.length();
		if (value.charAt(0) == '/') {
			pos = 1;
		}
		if (value.charAt(posend - 1) == '/') {
			posend -= 1;
		}
		if (posend <= pos) {
			return null;
		}
		value = value.substring(pos, posend);
		return value;
	}

	/* @Override */
	public bool isValidValue(string value) {
		return normalizeValue(value) != null;
	}

	/* @Override */
	public IDSQLResolution generateIDSQLResolution(FilterAtom atom) {
		return null; // Id resolution not needed
	}
}
